    throw new Error('path must be relative to the data directory');
  }
  const resolved = path.resolve(dataDir, userPath);
  const rel = path.relative(dataDir, resolved);
  if (rel.startsWith('..') || path.isAbsolute(rel) || rel === '') {
    throw new Error('path traversal outside the data directory is not allowed');
  }
  return { resolved, rel };
}

export async function listTools() {
  return Object.values(TOOLS);
}

export async function callTool(name, args) {
  const tool = TOOLS[name];
  if (!tool) {
    throw new Error(`Unknown tool: ${name}`);
  }

  const arguments_ = args ?? {};
